{
  "headline": "FDA's records trace our supply to a plant classified VAI 1022 days before the shortage posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "The drug has been on FDA's shortage list since 2022-10-28 and remains listed as of 2026-10-21, a span of 48 months.",
      "cites": ["D5"]
    },
    {
      "text": "An FDA inspection of NuCare Pharmaceuticals Inc. (FEI 3003294404) ended 2020-01-10 and was classified VAI, with the classification letter dated 2020-02-26 — 1022 days before the shortage posting.",
      "cites": ["D4", "E8"]
    },
    {
      "text": "NuCare Pharmaceuticals Inc. is a registered plant that relabels the product and its most recent inspection was NAI on 2025-03-12.",
      "cites": ["E10"]
    },
    {
      "text": "Another registered plant, Asclemed USA Inc. DBA Enovachem (FEI 3001452204), received an OAI classification after an inspection ending 2018-09-27 and a Warning Letter on 2019-06-11.",
      "cites": ["E14", "E15", "E16"]
    },
    {
      "text": "Corvale East holds 294 units of the 200 mg/5 mL + 28.5 mg/5 mL 100 mL presentation with 19.2 days on hand; Corvale General holds 425 units of the same presentation with 27.3 days on hand and 397 units of the 400 mg/5 mL 50 mL presentation with 26 days on hand.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule-based best option is to buy from Hikma Pharmaceuticals USA Inc., which is not on FDA's shortage list today and operates plants in Jordan (2INAMOXU24N-E and 2INAMOXU12N).",
      "cites": ["D6"]
    },
    {
      "text": "Additional alternate manufacturers not on the shortage list include Sandoz Inc. and Teva Pharmaceuticals USA, Inc..",
      "cites": ["D7", "D8"]
    }
  ]
}
